function v({registerIndicator:w,nulls:b}){w({id:"oa-dem",name:"DeMarker Oscillator (DEM)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1,tooltip:"Smoothing period over which the up and down extensions are summed. Traditional value is 14."}],plots:[{key:"dem",type:"line",title:"DEM",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:.7,title:"Overbought",color:"#ff5252",dashed:!0},{price:.5,title:"Midline",color:"#787b86",dashed:!0},{price:.3,title:"Oversold",color:"#4caf50",dashed:!0}],calc(r,x){const l=Math.max(1,Math.min(5e3,Math.floor(Number(x.period)||14))),d=r.length,c=new Array(d).fill(NaN),m=new Array(l).fill(0),h=new Array(l).fill(0);let e=0,o=0,a=0;for(let t=0;t<d;t++){const i=r[t],n=t>0?r[t-1]:i,g=Number.isFinite(n.high)?n.high:i.high,y=Number.isFinite(n.low)?n.low:i.low,u=i.high-g,p=y-i.low,M=Number.isFinite(u)?Math.max(u,0):0,f=Number.isFinite(p)?Math.max(p,0):0;o-=m[e],a-=h[e],m[e]=M,h[e]=f,o+=M,a+=f,e=(e+1)%l;const s=o+a;c[t]=Number.isFinite(s)&&s!==0?o/s:.5}return{dem:b(c)}}})}export{v as default};
